import com.coss.Coss;
import com.coss.resources.email.contacts.requests.UpsertContactRequest;
import com.coss.resources.email.contacts.types.UpsertContactRequestPropertiesValue;
import com.coss.resources.email.contacts.types.UpsertContactRequestTopicsItem;
import com.coss.resources.email.contacts.types.UpsertContactRequestTopicsItemStatus;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Optional;

Coss client = Coss.builder().build(); // .apiKey(…) or COSS_API_KEY

client.email().contacts().upsert(
    UpsertContactRequest
        .builder()
        .email("ada@example.com")
        .firstName(
            OptionalNullable.of("Ada")
        )
        .properties(
            new HashMap<String, OptionalNullable<UpsertContactRequestPropertiesValue>>() {{
                put("plan", OptionalNullable.of(
                    UpsertContactRequestPropertiesValue.of("pro")
                ));
            }}
        )
        .topics(
            Optional.of(
                Arrays.asList(
                    UpsertContactRequestTopicsItem
                        .builder()
                        .topic("newsletter")
                        .status(UpsertContactRequestTopicsItemStatus.OPTED_IN)
                        .build()
                )
            )
        )
        .build()
);

