import com.coss.types.SegmentFilterConditionsItemConditions;
import com.coss.types.SegmentFilterConditionsItemConditionsConditionsItem;
import com.coss.types.SegmentFilterConditionsItemConditionsConditionsItemAudience;
import com.coss.types.SegmentFilterConditionsItemConditionsConditionsItemAudienceOp;
import com.coss.types.SegmentFilterConditionsItemConditionsConditionsItemEmail;
import com.coss.types.SegmentFilterConditionsItemConditionsConditionsItemEmailOp;
import com.coss.types.SegmentFilterConditionsItemConditionsMatch;
import com.coss.types.SegmentFilterConditionsItemKey;
import com.coss.types.SegmentFilterConditionsItemKeyField;
import com.coss.types.SegmentFilterConditionsItemKeyOp;
import com.coss.types.SegmentFilterConditionsItemKeyValue;
import com.coss.types.SegmentFilterMatch;
import java.util.Arrays;
import java.util.Optional;

