import com.coss.Coss;
import com.coss.resources.risk.rules.requests.CreateRiskRuleRequest;
import com.coss.types.RiskDecision;
import com.coss.types.RiskEvent;
import com.coss.types.RiskRuleCondition;
import com.coss.types.RiskRuleConditionField;
import com.coss.types.RiskRuleConditionOperator;
import com.coss.types.RiskRuleConditionValue;
import java.util.Arrays;
import java.util.Optional;

Coss client = Coss.builder().build(); // .apiKey(…) or COSS_API_KEY

client.risk().rules().create(
    CreateRiskRuleRequest
        .builder()
        .name("Disposable email from a data center")
        .action(RiskDecision.BLOCK)
        .conditions(
            Arrays.asList(
                RiskRuleCondition
                    .builder()
                    .field(RiskRuleConditionField.EMAIL_DISPOSABLE)
                    .operator(RiskRuleConditionOperator.IS)
                    .value(
                        RiskRuleConditionValue.of(true)
                    )
                    .build(),
                RiskRuleCondition
                    .builder()
                    .field(RiskRuleConditionField.IP_HOSTING)
                    .operator(RiskRuleConditionOperator.IS)
                    .value(
                        RiskRuleConditionValue.of(true)
                    )
                    .build()
            )
        )
        .events(
            Optional.of(
                Arrays.asList(RiskEvent.SIGNUP)
            )
        )
        .build()
);

